mapper.select:
select ke.account_id, so.order_id, so.inbound_detail_id, ke.final_amount, ke.final_at, so.sell_qty, id.purchase_fx_rate, id.purchase_price, concat(fp.ticker, ' ', fp.name) as product_label from krw_exchange ke join sell_order so on so.order_id = ke.order_id join inbound_detail id on id.inbound_detail_id = so.inbound_detail_id join foreign_product fp on fp.foreign_product_id = id.foreign_product_id where ke.account_id in
#{accountId}
and ke.settlement_status = 'FINALIZED' and so.status = 'EXECUTED' and YEAR(ke.final_at) = #{year} and #{calcBaseTime} >= ke.final_at

select ke.account_id, so.order_id, so.inbound_detail_id, ke.provisional_amount as final_amount, ke.final_at, so.sell_qty, id.purchase_fx_rate, id.purchase_price, concat(fp.ticker, ' ', fp.name) as product_label from krw_exchange ke join sell_order so on so.order_id = ke.order_id join inbound_detail id on id.inbound_detail_id = so.inbound_detail_id join foreign_product fp on fp.foreign_product_id = id.foreign_product_id where ke.account_id in
#{accountId}
and ke.settlement_status = 'PROVISIONAL' and so.status = 'EXECUTED' and YEAR(ke.final_at) = #{year} and #{calcBaseTime} >= ke.provisional_at

select a.account_id, tpj.trade_date, tpj.net_buy_amount, coalesce(tpj.fund_name, tpj.ticker) as product_label from target_product_judgement tpj join customer c on c.ci_hash = tpj.ci_hash join account a on a.customer_id = c.customer_id where a.account_id in
#{accountId}
and tpj.is_target = true and YEAR(tpj.trade_date) = #{year} and #{calcBaseTime} >= tpj.judged_at

select exists(
    select 1
    from tax_calculation
    where account_id = #{accountId} and basis_type = #{basisType}
)

select count(distinct account_id)
from account_benefit_log
where changed_at between #{since} and #{until}
